using System;

class Program
{
    static void Main()
    {
        int a = 42;
        System.Int32 b = 42;          // identical to int
        string s = "hi";

        Console.WriteLine(a.GetType());            // System.Int32
        Console.WriteLine(b.GetType() == a.GetType()); // True
        Console.WriteLine(s.GetType().IsValueType);    // False (reference type)
        Console.WriteLine(Environment.Version);        // runtime version, e.g. 8.0.x
    }
}

