using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var map = new Dictionary<string, string[]>();
        map["bool"] = new string[] { "System.Boolean", "1" };
        map["byte"] = new string[] { "System.Byte", "1" };
        map["sbyte"] = new string[] { "System.SByte", "1" };
        map["char"] = new string[] { "System.Char", "2" };
        map["short"] = new string[] { "System.Int16", "2" };
        map["ushort"] = new string[] { "System.UInt16", "2" };
        map["int"] = new string[] { "System.Int32", "4" };
        map["uint"] = new string[] { "System.UInt32", "4" };
        map["long"] = new string[] { "System.Int64", "8" };
        map["ulong"] = new string[] { "System.UInt64", "8" };
        map["float"] = new string[] { "System.Single", "4" };
        map["double"] = new string[] { "System.Double", "8" };
        map["decimal"] = new string[] { "System.Decimal", "16" };
        map["string"] = new string[] { "System.String", "ref" };
        map["object"] = new string[] { "System.Object", "ref" };
        var nonCls = new HashSet<string> { "sbyte", "ushort", "uint", "ulong" };

        string[] lines = Console.In.ReadToEnd().Replace("\r", "").Split('\n');
        int n = int.Parse(lines[0].Trim());
        int values = 0, refs = 0, unknown = 0, notCls = 0;
        for (int i = 1; i <= n; i++)
        {
            string name = i < lines.Length ? lines[i].Trim() : "";
            string[] info;
            if (!map.TryGetValue(name, out info))
            {
                Console.WriteLine(name + " => not a C# built-in alias");
                unknown++;
                continue;
            }
            if (info[1] == "ref")
            {
                Console.WriteLine(name + " => " + info[0] + " | reference type");
                refs++;
                continue;
            }
            string line = name + " => " + info[0] + " | value type | " + info[1] + (info[1] == "1" ? " byte" : " bytes");
            if (nonCls.Contains(name))
            {
                line += " | not CLS-compliant";
                notCls++;
            }
            Console.WriteLine(line);
            values++;
        }
        Console.WriteLine("Summary: " + values + " value, " + refs + " reference, " + unknown + " unknown, " + notCls + " not CLS-compliant");
    }
}
